G=load(); print(sorted(G))
def solve(inp):
    bg=max(set(x for r in inp for x in r), key=lambda v:sum(r.count(v) for r in inp))
    h=len(inp); w=len(inp[0])
    pts=[(i,j,v) for i,r_ in enumerate(inp) for j,v in enumerate(r_) if v!=bg]
    out=[[bg]*w for _ in range(h)]
    for rr in range(h):
        for cc in range(w):
            if inp[rr][cc]!=bg: continue
            best=None
            for i,j,v in pts:
                if abs(rr-i)<=1:  # within band rows
                    d=(abs(rr-i)+abs(cc-j), i+j)
                    if best is None or d<best[0]: best=(d,v,i,j)
            if best and (rr+cc)%2==best[0][1]%2: out[rr][cc]=best[1]
    return out
